import React from "react";
import {AbsoluteFill, interpolate, spring, useCurrentFrame, useVideoConfig} from "remotion";

export const C = {bg: "#0b0e14", panel: "#141925", line: "#2a3245", text: "#f2f4f8", dim: "#9aa3b8", accent: "#7cf0c4", ink: "#06120d"};
export const FONT = "Segoe UI, system-ui, sans-serif";
export const MONO = "Consolas, 'Cascadia Mono', monospace";
export const clamp = {extrapolateLeft: "clamp" as const, extrapolateRight: "clamp" as const};

export const useIn = (delay: number, damping = 200) => {
  const frame = useCurrentFrame();
  const {fps} = useVideoConfig();
  return spring({frame: frame - delay, fps, config: {damping}});
};

export const Reveal: React.FC<{delay: number; y?: number; style?: React.CSSProperties; children: React.ReactNode}> = ({delay, y = 40, style, children}) => {
  const p = useIn(delay);
  return <div style={{opacity: p, transform: `translateY(${interpolate(p, [0, 1], [y, 0])}px)`, ...style}}>{children}</div>;
};

export const Frame: React.FC<{n: number; kicker?: string; children: React.ReactNode}> = ({n, kicker = "JARVIS", children}) => {
  const frame = useCurrentFrame();
  const {durationInFrames} = useVideoConfig();
  const out = interpolate(frame, [durationInFrames - 12, durationInFrames], [1, 0], clamp);
  return (
    <AbsoluteFill style={{background: `radial-gradient(1200px 700px at 85% 10%, #131b2b 0%, ${C.bg} 70%)`, color: C.text, fontFamily: FONT, opacity: out}}>
      <div style={{position: "absolute", left: 120, top: 70, fontSize: 28, letterSpacing: 8, color: C.accent, fontWeight: 700}}>{kicker}</div>
      <div style={{position: "absolute", right: 120, bottom: 60, fontSize: 28, color: C.dim, fontFamily: MONO}}>{n} / 4</div>
      <AbsoluteFill style={{padding: "150px 120px 110px"}}>{children}</AbsoluteFill>
    </AbsoluteFill>
  );
};

