import React from "react";
import {interpolate, useCurrentFrame} from "remotion";
import {C, Frame, Reveal, MONO, clamp, useIn} from "./lib/kit";

const NODES = [
  {t: "F9", s: "Appui"},
  {t: "Transcription", s: "Voix en texte"},
  {t: "Agent", s: "Décide"},
  {t: "Outils", s: "Mémoire, board"},
  {t: "Voix", s: "Réponse parlée"},
];
const W = 260;
const STEP = 355;

const Node: React.FC<{i: number; active: boolean}> = ({i, active}) => {
  const p = useIn(30 + i * 26, 16);
  const n = NODES[i];
  return (
    <div style={{position: "absolute", left: i * STEP, top: 0, width: W, height: 220, borderRadius: 24, background: C.panel, border: `3px solid ${active ? C.accent : C.line}`, boxShadow: active ? `0 0 60px ${C.accent}44` : "none", opacity: p, transform: `scale(${0.85 + 0.15 * p})`, display: "flex", flexDirection: "column", alignItems: "center", justifyContent: "center", gap: 14}}>
      <div style={{fontSize: 46, fontWeight: 700, color: active ? C.accent : C.text, fontFamily: i === 0 ? MONO : undefined}}>{n.t}</div>
      <div style={{fontSize: 30, color: C.dim}}>{n.s}</div>
    </div>
  );
};

const Link: React.FC<{i: number}> = ({i}) => {
  const frame = useCurrentFrame();
  const f = interpolate(frame, [48 + i * 26, 70 + i * 26], [0, 1], clamp);
  return (
    <div style={{position: "absolute", left: i * STEP + W + 8, top: 108, width: STEP - W - 16, height: 4, background: C.line, borderRadius: 2}}>
      <div style={{width: `${f * 100}%`, height: 4, background: C.accent, borderRadius: 2}} />
      <div style={{position: "absolute", right: -4, top: -10, width: 0, height: 0, borderLeft: `18px solid ${f > 0.95 ? C.accent : C.line}`, borderTop: "12px solid transparent", borderBottom: "12px solid transparent"}} />
    </div>
  );
};

export default function Scene() {
  const frame = useCurrentFrame();
  const active = frame < 190 ? -1 : Math.floor((frame - 190) / 20) % 5;
  return (
    <Frame n={2}>
      <Reveal delay={0}><div style={{fontSize: 100, fontWeight: 800}}>De la voix à la réponse</div></Reveal>
      <div style={{position: "relative", marginTop: 170, height: 220}}>
        {NODES.map((_, i) => <Node key={i} i={i} active={active === i} />)}
        {NODES.slice(0, 4).map((_, i) => <Link key={i} i={i} />)}
      </div>
      <Reveal delay={200} style={{marginTop: 110}}><div style={{fontSize: 48, color: C.dim}}>Chaque maillon est <span style={{color: C.accent}}>remplaçable</span>.</div></Reveal>
    </Frame>
  );
}

