import React from "react";
import {C, Stage, Reveal, MONO, useIn} from "./lib/kit";
import {useCurrentFrame} from "remotion";

const TOOLS = ["memory_search", "memory_append", "board_present"];

const Tool: React.FC<{name: string; i: number}> = ({name, i}) => {
  const p = useIn(25 + i * 14);
  const hot = name === "memory_append";
  return (
    <div style={{opacity: p, transform: `translateX(${(1 - p) * -60}px)`, background: C.panel, border: `2px solid ${hot ? C.accent : C.line}`, borderRadius: 18, padding: "28px 32px", fontFamily: MONO, fontSize: 36, display: "flex", alignItems: "center", gap: 20}}>
      <span style={{width: 16, height: 16, borderRadius: 8, background: hot ? C.accent : C.dim}} />
      {name}
    </div>
  );
};

const Row: React.FC<{delay: number; answer: string; ok: boolean}> = ({delay, answer, ok}) => {
  const frame = useCurrentFrame();
  const row = useIn(delay);
  const bubble = useIn(delay + 35, 12);
  const done = frame >= delay + 60;
  const status = useIn(delay + 60, 14);
  return (
    <div style={{opacity: row, display: "flex", alignItems: "center", justifyContent: "space-between", padding: "26px 0", borderTop: `1px solid ${C.line}`}}>
      <div>
        <div style={{fontFamily: MONO, fontSize: 28, color: C.dim}}>memory_append</div>
        <div style={{fontSize: 40, marginTop: 8}}>Ajouter à la mémoire ?</div>
      </div>
      <div style={{display: "flex", alignItems: "center", gap: 24}}>
        <div style={{transform: `scale(${bubble})`, opacity: bubble, fontFamily: MONO, fontSize: 40, fontWeight: 700, padding: "10px 30px", borderRadius: 40, border: `2px solid ${C.text}`}}>{answer}</div>
        <div style={{width: 230, textAlign: "center", fontSize: 34, fontWeight: 700, padding: "12px 0", borderRadius: 14, background: done && ok ? C.accent : "transparent", color: done ? (ok ? C.ink : C.dim) : C.dim, border: `2px solid ${done && ok ? C.accent : C.line}`, transform: done ? `scale(${0.9 + 0.1 * status})` : undefined}}>
          {done ? (ok ? "Écrit" : "Refusé") : "En attente"}
        </div>
      </div>
    </div>
  );
};

export default function Scene() {
  return (
    <Stage n={3}>
      <Reveal delay={0}><div style={{fontSize: 88, fontWeight: 800}}>Rien n'est écrit sans votre <span style={{color: C.accent}}>« oui »</span></div></Reveal>
      <div style={{display: "flex", gap: 80, marginTop: 90, alignItems: "flex-start"}}>
        <div style={{width: 560, display: "flex", flexDirection: "column", gap: 24}}>
          <Reveal delay={15}><div style={{fontSize: 30, color: C.dim, letterSpacing: 4, marginBottom: 4}}>TROIS OUTILS</div></Reveal>
          {TOOLS.map((t, i) => <Tool key={t} name={t} i={i} />)}
        </div>
        <Reveal delay={60} style={{flex: 1}}>
          <div style={{background: C.panel, border: `2px solid ${C.line}`, borderRadius: 24, padding: "20px 44px 28px"}}>
            <div style={{display: "flex", gap: 10, padding: "10px 0 22px"}}>{[0, 1, 2].map((k) => <span key={k} style={{width: 14, height: 14, borderRadius: 7, background: C.line}} />)}</div>
            <Row delay={80} answer="oui" ok={true} />
            <Row delay={170} answer="non" ok={false} />
          </div>
          <div style={{fontSize: 36, color: C.dim, marginTop: 36}}>Refus par défaut.</div>
        </Reveal>
      </div>
    </Stage>
  );
}

