import React from "react";
import {interpolate, useCurrentFrame} from "remotion";
import {C, Stage, Reveal, MONO, clamp, useIn} from "./lib/kit";

const Box: React.FC<{delay: number; title: string; sub: string; hot?: boolean}> = ({delay, title, sub, hot}) => {
  const p = useIn(delay, 18);
  return (
    <div style={{width: 640, height: 230, borderRadius: 26, background: C.panel, border: `3px solid ${hot ? C.accent : C.line}`, opacity: p, transform: `scale(${0.88 + 0.12 * p})`, display: "flex", flexDirection: "column", justifyContent: "center", alignItems: "center", gap: 14}}>
      <div style={{fontSize: 68, fontWeight: 800, color: hot ? C.accent : C.text}}>{title}</div>
      <div style={{fontSize: 36, color: C.dim}}>{sub}</div>
    </div>
  );
};

const Bridge: React.FC = () => {
  const frame = useCurrentFrame();
  const f = interpolate(frame, [60, 90], [0, 1], clamp);
  const t = ((frame - 90) / 45) % 1;
  const dot = frame > 90 ? t : 0;
  return (
    <div style={{position: "relative", width: 280, height: 6, background: C.line, borderRadius: 3, margin: "0 20px"}}>
      <div style={{width: `${f * 100}%`, height: 6, background: C.accent, borderRadius: 3}} />
      {frame > 90 && <div style={{position: "absolute", top: -9, left: `${dot * 100}%`, width: 24, height: 24, borderRadius: 12, background: C.accent, boxShadow: `0 0 24px ${C.accent}`}} />}
    </div>
  );
};

const CMD = "python scripts/dev_start.py";

const Terminal: React.FC = () => {
  const frame = useCurrentFrame();
  const p = useIn(130);
  const n = Math.floor(interpolate(frame, [150, 150 + CMD.length * 2], [0, CMD.length], clamp));
  const caret = Math.floor(frame / 15) % 2 === 0;
  return (
    <div style={{opacity: p, transform: `translateY(${(1 - p) * 40}px)`, background: "#05070b", border: `2px solid ${C.line}`, borderRadius: 20, padding: "34px 48px", fontFamily: MONO, fontSize: 52, display: "flex", alignItems: "center"}}>
      <span style={{color: C.accent, marginRight: 24}}>$</span>
      <span>{CMD.slice(0, n)}</span>
      <span style={{display: "inline-block", width: 26, height: 56, marginLeft: 6, background: caret ? C.accent : "transparent"}} />
    </div>
  );
};

export default function Scene() {
  return (
    <Stage n={4}>
      <Reveal delay={0}><div style={{fontSize: 96, fontWeight: 800}}>Des réflexes, un <span style={{color: C.accent}}>cerveau</span></div></Reveal>
      <div style={{display: "flex", alignItems: "center", justifyContent: "center", marginTop: 60}}>
        <Box delay={25} title="Surface" sub="Réflexes" />
        <Bridge />
        <Box delay={45} title="Cerveau" sub="Vérité" hot />
      </div>
      <Reveal delay={95}><div style={{textAlign: "center", fontFamily: MONO, fontSize: 30, color: C.dim, marginTop: 24}}>mode continuous_brain, optionnel</div></Reveal>
      <div style={{marginTop: 60}}><Terminal /></div>
    </Stage>
  );
}

