import React from "react";
import {useCurrentFrame} from "remotion";
import {C, Stage, Reveal, MONO, useIn} from "./lib/kit";

const Letter: React.FC<{ch: string; i: number}> = ({ch, i}) => {
  const p = useIn(i * 4, 14);
  return <span style={{display: "inline-block", opacity: p, transform: `translateY(${(1 - p) * 90}px)`}}>{ch}</span>;
};

const Wave: React.FC = () => {
  const frame = useCurrentFrame();
  const p = useIn(30);
  return (
    <div style={{display: "flex", alignItems: "center", gap: 14, height: 520, opacity: p}}>
      {Array.from({length: 17}).map((_, i) => {
        const env = 1 - Math.abs(i - 8) / 10;
        const h = 40 + 440 * env * (0.3 + 0.7 * Math.abs(Math.sin(frame / 8 + i * 0.7)));
        return <div key={i} style={{width: 22, height: h * p, borderRadius: 11, background: C.accent, opacity: 0.35 + 0.65 * env}} />;
      })}
    </div>
  );
};

export default function Scene() {
  return (
    <Stage n={1} kicker="">
      <div style={{display: "flex", height: "100%", alignItems: "center", justifyContent: "space-between"}}>
        <div>
          <div style={{fontSize: 230, fontWeight: 800, letterSpacing: 10, lineHeight: 1}}>
            {"JARVIS".split("").map((c, i) => <Letter key={i} ch={c} i={i} />)}
          </div>
          <Reveal delay={40}><div style={{fontSize: 68, color: C.accent, marginTop: 30}}>L'assistant vocal local.</div></Reveal>
          <Reveal delay={70}>
            <div style={{display: "flex", alignItems: "center", gap: 22, marginTop: 56, fontSize: 40}}>
              <span style={{fontFamily: MONO, border: `2px solid ${C.accent}`, color: C.accent, borderRadius: 12, padding: "6px 26px", fontWeight: 700}}>F9</span>
              <span style={{color: C.dim}}>pour lui parler</span>
            </div>
          </Reveal>
        </div>
        <Wave />
      </div>
    </Stage>
  );
}

